create or replace package body t009_checkout_api as
  function order_total(p_order_id in number) return number is
    l_items_total_price number;
    l_physical_item_count number;
    l_shipping_cost number;
  begin
    -- Calculate total price of items
    select nvl(sum(price * qty), 0)
      into l_items_total_price
      from t009_order_items
     where order_id = p_order_id;

    -- Check if the order contains any physical items
    select count(1)
      into l_physical_item_count
      from t009_order_items
     where order_id = p_order_id
       and is_physical = 'Y'; -- Assuming 'is_physical' column exists and 'Y' means physical

    l_shipping_cost := t009_shipping_pkg.shipping_cost(p_order_id);

    if l_physical_item_count > 0 then
      return l_items_total_price + l_shipping_cost;
    else
      -- Digital items ship for free
      return l_items_total_price;
    end if;

  end order_total;
end t009_checkout_api;
/
